## Why This Is Asked

This question tests understanding of Go-C interop boundaries, memory ownership, and callback-based asynchronous flows in CGO. The candidate must design a safe pattern for per-input callbacks, ordering guarantees, and memory cleanup under concurrency.

## Key Concepts

- CGO callbacks and //export directives
- Cross-language memory management (malloc/free)
- Synchronization and ordering in Go when callbacks arrive from C
- Safe memory copying between C and Go heaps

## Code Example

```go
package main

/*
#include <stdlib.h>
#include <string.h>

typedef struct {
    void *ctx;
    int index;
    const char *result;
    size_t len;
} CallbackContext;

extern void goCallback(CallbackContext *cbCtx);

static int batch_process_wrapper(
    const char **inputs,
    size_t n,
    void (*cb)(const char *result, size_t len, void *ctx),
    void *ctx
) {
    for (size_t i = 0; i < n; i++) {
        cb(inputs[i], strlen(inputs[i]), ctx);
    }
    return 0;
}

static void cCallback(const char *result, size_t len, void *ctx) {
    CallbackContext *cbCtx = (CallbackContext *)ctx;
    cbCtx->result = result;
    cbCtx->len = len;
    goCallback(cbCtx);
}

//export goCallback
extern void goCallback(CallbackContext *cbCtx);
*/
import "C"

import (
    "fmt"
    "sync"
    "unsafe"
)

type Result struct {
    Index int
    Data  string
    Err   error
}

func BatchProcess(inputs []string) ([]string, error) {
    if len(inputs) == 0 {
        return []string{}, nil
    }

    cInputs := make([]*C.char, len(inputs))
    defer func() {
        for _, cStr := range cInputs {
            C.free(unsafe.Pointer(cStr))
        }
    }()

    for i, s := range inputs {
        cStr := C.CString(s)
        cInputs[i] = cStr
    }

    results := make([]string, len(inputs))
    var wg sync.WaitGroup
    resultCh := make(chan Result, len(inputs))

    ctx := C.malloc(C.sizeof_char * C.size_t(len(inputs)))
    defer C.free(ctx)

    wrapper := func() {
        defer wg.Done()
        for i := 0; i < len(inputs); i++ {
            callbackCtx := &C.CallbackContext{
                ctx:   ctx,
                index: C.int(i),
            }
            ret := C.batch_process_wrapper((**C.char)(unsafe.Pointer(&cInputs[i])), 1, C.cCallback, unsafe.Pointer(callbackCtx))
            if ret != 0 {
                resultCh <- Result{Index: i, Err: fmt.Errorf("batch_process failed with code %d", ret)}
                return
            }
        }
    }

    wg.Add(1)
    go wrapper()

    go func() {
        wg.Wait()
        close(resultCh)
    }()

    for result := range resultCh {
        if result.Err != nil {
            return nil, result.Err
        }
        results[result.Index] = result.Data
    }

    return results, nil
}

func main() {
    inputs := []string{"hello", "world", "foo", "bar"}

    var wg sync.WaitGroup
    for i := 0; i < 4; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            results, err := BatchProcess(inputs)
            if err != nil {
